#include <cassert>
#include <cstddef>
#include <iostream>
#include <limits>
#include <unordered_set>
#include <vector>

struct EventNode { int code; const EventNode* next; };

// 순환이 있다면 head에서 처음 진입하는 원본 노드 주소를 반환합니다.
// 전제: 도달 가능한 노드는 살아 있으며, 호출 도중 연결이 바뀌지 않습니다.
const EventNode* FindLoopEntry(const EventNode* head) {
    const EventNode* slow = head;
    const EventNode* fast = head;
    while (fast != nullptr && fast->next != nullptr) {
        slow = slow->next;             // 한 칸 이동
        fast = fast->next->next;       // 두 칸 이동: 앞의 조건이 접근을 보호
        if (slow == fast) {            // 시작 시가 아니라 이동 후 주소 비교
            const EventNode* entry = head;
            while (entry != slow) {    // 이제 두 포인터 모두 한 칸씩 이동
                entry = entry->next;
                slow = slow->next;
            }
            return entry;
        }
    }
    return nullptr;                    // 끝에 닿으면 순환이 없습니다.
}

// 검증 전용 기준 풀이: 주소를 처음 다시 만나는 지점이 순환 입구입니다.
// 이 함수의 O(n) 추가 메모리는 위 풀이의 O(1) 공간과 별개입니다.
const EventNode* Oracle(const EventNode* head) {
    std::unordered_set<const EventNode*> seen;
    for (const EventNode* p = head; p != nullptr; p = p->next)
        if (!seen.insert(p).second) return p;
    return nullptr;
}

void CheckUnchanged(const std::vector<EventNode>& nodes,
                    const std::vector<EventNode>& before) {
    assert(nodes.size() == before.size());
    for (std::size_t i = 0; i < nodes.size(); ++i) {
        assert(nodes[i].code == before[i].code);
        assert(nodes[i].next == before[i].next);
    }
}

// entry == n이면 비순환, entry < n이면 마지막 노드가 entry로 돌아갑니다.
void CheckChain(std::size_t n, std::size_t entry) {
    assert(entry <= n);
    std::vector<EventNode> nodes(n); // 먼저 확정 크기로 확보한 뒤 주소를 연결
    for (std::size_t i = 0; i < n; ++i) {
        nodes[i].code = 7;          // 모든 값이 같아도 객체 주소는 다릅니다.
        nodes[i].next = i + 1 < n ? &nodes[i + 1] : nullptr;
    }
    if (n != 0 && entry < n) nodes[n - 1].next = &nodes[entry];
    const std::vector<EventNode> before = nodes;
    const EventNode* head = n == 0 ? nullptr : &nodes[0];
    const EventNode* expected = entry < n ? &nodes[entry] : nullptr;
    assert(FindLoopEntry(head) == expected);
    assert(Oracle(head) == expected);
    CheckUnchanged(nodes, before);
    // vector가 각 원소를 소유합니다. next를 따라 삭제하면 안 됩니다.
}

int main() {
    assert(FindLoopEntry(nullptr) == nullptr);
    // 값의 최솟값/최댓값은 허용되지만 순환 판정에는 영향을 주지 않습니다.
    EventNode b = {std::numeric_limits<int>::max(), nullptr};
    EventNode a = {std::numeric_limits<int>::min(), &b};
    assert(FindLoopEntry(&a) == nullptr);
    b.next = &a;
    assert(FindLoopEntry(&a) == &a);
    assert(a.code == std::numeric_limits<int>::min() && a.next == &b);
    assert(b.code == std::numeric_limits<int>::max() && b.next == &a);

    std::size_t chains = 0;
    for (std::size_t n = 0; n <= 128; ++n) {
        CheckChain(n, n);
        ++chains;
    }
    // 접두부 길이 mu=0..64, 순환 길이 lambda=1..64의 모든 조합
    for (std::size_t mu = 0; mu <= 64; ++mu)
        for (std::size_t lambda = 1; lambda <= 64; ++lambda) {
            CheckChain(mu + lambda, mu);
            ++chains;
        }

    // 0..5개 노드 각각의 next를 null 또는 임의 노드로 지정합니다.
    // 도달 불가능한 순환도 포함하며, 모든 시작점(null 포함)을 비교합니다.
    std::size_t graphCases = 0;
    for (std::size_t n = 0; n <= 5; ++n) {
        std::size_t configs = 1;
        for (std::size_t i = 0; i < n; ++i) configs *= n + 1;
        for (std::size_t c = 0; c < configs; ++c) {
            std::vector<EventNode> nodes(n);
            std::size_t digits = c;
            for (std::size_t i = 0; i < n; ++i) {
                const std::size_t target = digits % (n + 1);
                digits /= n + 1;
                nodes[i].code = 7;
                nodes[i].next = target == n ? nullptr : &nodes[target];
            }
            const std::vector<EventNode> before = nodes;
            for (std::size_t start = 0; start <= n; ++start) {
                const EventNode* head = start == n ? nullptr : &nodes[start];
                assert(FindLoopEntry(head) == Oracle(head));
                CheckUnchanged(nodes, before);
                ++graphCases;
            }
        }
    }
    CheckChain(100000, 100000); // 긴 비순환
    CheckChain(100000, 0);      // head가 순환 입구
    CheckChain(100000, 1);      // 짧은 접두부와 긴 순환
    CheckChain(100000, 50000);  // 중간 입구
    CheckChain(100000, 99999);  // 긴 접두부와 자기 순환
    std::cout << "PASS: " << chains << " chain shapes, " << graphCases
              << " functional-graph head cases, 5 x 100000-node cases; values/links preserved\n";
}
